            "uri": "mcp://aws-iam-mcp",
            "allowed_arn_prefix": "arn:aws:iam::111122223333:role/DevSandbox-"
        }
    }

    server_name = proposed_call.get("server")
    tool = proposed_call.get("tool")
    args = proposed_call.get("args", {})
    jwt_aud = proposed_call.get("jwt_aud")
    tenant_id = proposed_call.get("tenant_id")

    # Clause 0: Token audience
    expected_aud = SERVERS.get(server_name, {}).get("uri")
    if expected_aud and jwt_aud != expected_aud:
        return {"allow": False, "reason": f"jwt_aud mismatch: expected {expected_aud}, got {jwt_aud}"}

    server_info = SERVERS.get(server_name, {})
    trust_level = server_info.get("trust_level")

    # Helper: extract qualifying strings (length >= 4) from output
    def extract_qualifying_strings(obj):
        strings = []
        if isinstance(obj, str):
            if len(obj) >= 4:
                strings.append(obj)
        elif isinstance(obj, dict):
            for v in obj.values():
                strings.extend(extract_qualifying_strings(v))
        elif isinstance(obj, list):
            for item in obj:
                strings.extend(extract_qualifying_strings(item))
        return strings

    # Helper: extract qualifying strings from args
    def extract_args_strings(args_dict):
        strings = []
        if isinstance(args_dict, dict):
            for v in args_dict.values():
                if isinstance(v, str) and len(v) >= 4:
                    strings.append(v)
                elif isinstance(v, (dict, list)):
                    strings.extend(extract_qualifying_strings(v))
        return strings

    # Clause 1: Exfiltration to less-trusted server
    if trust_level in ("untrusted_third_party", "untrusted_external"):
        # Check args for postgres URIs
        for s in extract_args_strings(args):
            if s.startswith("postgres://") or s.startswith("postgresql://"):
                return {"allow": False, "reason": "Database connection URI in args to untrusted server"}

        # Check args for qualifying strings from privileged server outputs
        privileged_levels = {"privileged_internal", "privileged_cloud", "privileged_secrets", "privileged_financial", "privileged_local"}
        tainted_strings = set()
        for entry in session_log:
            entry_server = entry.get("server")
            entry_info = SERVERS.get(entry_server, {})
            if entry_info.get("trust_level") in privileged_levels:
                output = entry.get("output", {})
                tainted_strings.update(extract_qualifying_strings(output))

        for s in extract_args_strings(args):
            for tainted in tainted_strings:
                if tainted in s:
                    return {"allow": False, "reason": "Qualifying string from privileged server output found in args to untrusted server"}

    # Clause 2: Unapproved schema change
    approved_domain = server_info.get("approved_domain")
