        schema_changed = False
        for entry in session_log:
            if entry.get("server") == server_name:
                if entry.get("type") == "notifications/tools/list_changed":
                    schema_changed = True
                elif entry.get("type") == "admin/reapprove_schema":
                    schema_changed = False
        if schema_changed:
            return {"allow": False, "reason": "Schema changed without reapproval"}

    # Clause 3: Untrusted fragments in role ARN
    if server_name == "aws-iam-mcp" and tool == "assume_role":
        role_arn = args.get("role_arn")
        allowed_prefix = server_info.get("allowed_arn_prefix")
        if not isinstance(role_arn, str) or not role_arn.startswith(allowed_prefix):
            return {"allow": False, "reason": f"role_arn must start with {allowed_prefix}"}

        # Check for qualifying strings from untrusted_external server outputs
        tainted_strings = set()
        for entry in session_log:
            entry_server = entry.get("server")
            entry_info = SERVERS.get(entry_server, {})
            if entry_info.get("trust_level") == "untrusted_external":
                output = entry.get("output", {})
                tainted_strings.update(extract_qualifying_strings(output))

        if isinstance(role_arn, str):
            for tainted in tainted_strings:
                if tainted in role_arn:
                    return {"allow": False, "reason": "role_arn contains qualifying string from untrusted_external server output"}

    # Clause 4: Secret path scope
    if server_name == "vault-mcp" and tool == "read_secret":
