        account_scoped_tools = server_info.get("account_scoped_tools", [])
        if tool in account_scoped_tools:
            account_id = args.get("account_id")
            expected = f"acct_{tenant_id}" if tenant_id else None
            if not isinstance(account_id, str) or not account_id or account_id != expected:
                return {"allow": False, "reason": f"account_id must be {expected}"}

    # Clause 7: Declared argument types
    typed_args = server_info.get("typed_arguments", {})
    tool_typed = typed_args.get(tool, {})
    for arg_name, spec in tool_typed.items():
