            continue
        value = args[arg_name]
        expected_type = spec.get("type")
        if expected_type == "string" and not isinstance(value, str):
            return {"allow": False, "reason": f"Argument {arg_name} must be string"}
        enum_vals = spec.get("enum")
        if enum_vals is not None and value not in enum_vals:
            return {"allow": False, "reason": f"Argument {arg_name} value not in enum"}
        prefixes = spec.get("prefixes")
        if prefixes is not None and isinstance(value, str):
            if not any(value.startswith(p) for p in prefixes):
                return {"allow": False, "reason": f"Argument {arg_name} must start with one of {prefixes}"}

    # Clause 8: Hotfix constraints for github-mcp
    if server_name == "github-mcp" and tool == "create_hotfix_branch":
        hotfix = server_info.get("hotfix_constraints", {})
        repo_prefix = hotfix.get("repo_prefix")
        repo_suffix = hotfix.get("repo_suffix")
        branch_prefix = hotfix.get("branch_prefix")
        repo = args.get("repo")
        branch = args.get("branch")
        if not (isinstance(repo, str) and repo.startswith(repo_prefix) and repo.endswith(repo_suffix)):
            return {"allow": False, "reason": "repo does not match prefix/suffix constraints"}
        if not (isinstance(branch, str) and branch.startswith(branch_prefix)):
            return {"allow": False, "reason": "branch does not match prefix constraint"}

    return {"allow": True, "reason": "Policy checks passed"}
